FastAPI application for the Settle expense-splitter.
"""

from decimal import Decimal
from pathlib import Path

import uvicorn
from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import FileResponse

import settle.db as db
import settle.ledger as ledger
from settle.models import (
    ExpenseCreate,
    ExpenseResponse,
    GroupCreate,
    GroupResponse,
    PaymentResponse,
    SettlementResponse,
)

app = FastAPI(title="Settle")

# ---------------------------------------------------------------------------
# Startup / shutdown — keep a single in-memory connection alive
# ---------------------------------------------------------------------------
_conn: db.sqlite3.Connection | None = None

@app.on_event("startup")
def _startup() -> None:
    global _conn
    _conn = db.init_db()

@app.on_event("shutdown")
def _shutdown() -> None:
    global _conn
    if _conn is not None:
        _conn.close()
        _conn = None

# ---------------------------------------------------------------------------
# Groups
# ---------------------------------------------------------------------------
@app.post("/api/groups", status_code=201)
def create_group(body: GroupCreate) -> GroupResponse:
    gid = db.create_group(_conn, body.name, body.members)
    return GroupResponse(id=gid, name=body.name, members=body.members)

@app.get("/api/groups")
def list_groups() -> list[GroupResponse]:
    return [GroupResponse(**g) for g in db.list_groups(_conn)]

# ---------------------------------------------------------------------------
# Expenses
# ---------------------------------------------------------------------------
@app.post("/api/expenses", status_code=201)
def create_expense(body: ExpenseCreate) -> ExpenseResponse:
    group = db.get_group(_conn, body.group_id)
    if group is None:
        raise HTTPException(status_code=404, detail=f"group {body.group_id} not found")

    members = group["members"]
    if body.payer not in members:
        raise HTTPException(
            status_code=400,
            detail=f"payer '{body.payer}' not a member of group {body.group_id}",
        )
    for name in body.split_among:
        if name not in members:
            raise HTTPException(
                status_code=400,
                detail=f"member '{name}' not in group {body.group_id}",
            )

    eid = db.create_expense(
        _conn,
        body.group_id,
        body.payer,
        body.amount,
        body.description,
        body.split_among,
    )
    return ExpenseResponse(
        id=eid,
        group_id=body.group_id,
        payer=body.payer,
        amount=body.amount,
        description=body.description,
    )

@app.get("/api/groups/{group_id}/expenses")
def list_expenses(group_id: int) -> list[ExpenseResponse]:
    group = db.get_group(_conn, group_id)
    if group is None:
        raise HTTPException(status_code=404, detail=f"group {group_id} not found")
    return [ExpenseResponse(**e) for e in db.get_expenses(_conn, group_id)]

# ---------------------------------------------------------------------------
# Settlement
# ---------------------------------------------------------------------------
@app.get("/api/groups/{group_id}/settlement")
def settlement(group_id: int) -> SettlementResponse:
    group = db.get_group(_conn, group_id)
    if group is None:
        raise HTTPException(status_code=404, detail=f"group {group_id} not found")

    expenses = db.get_expenses(_conn, group_id)
    ledger_expenses = [
        ledger.Expense(
            payer=e["payer"],
            amount=Decimal(str(e["amount"])),
            split_among=e["split_among"],
            description=e.get("description", ""),
        )
        for e in expenses
    ]
    balances = ledger.compute_balances(ledger_expenses)
    payments = ledger.settle(balances)

    return SettlementResponse(
        payments=[
            PaymentResponse(
                from_member=p.from_person,
                to_member=p.to_person,
                amount=float(p.amount),
            )
            for p in payments
        ]
    )

# ---------------------------------------------------------------------------
# SPA catch-all (serve static/index.html for any non-/api/ path)
# ---------------------------------------------------------------------------
STATIC_DIR = Path(__file__).resolve().parent / "static"

@app.get("/")
def spa_root() -> FileResponse:
    return FileResponse(STATIC_DIR / "index.html")

@app.get("/{path:path}")
def spa_catchall(path: str) -> FileResponse:
    if path.startswith("api/") or "/api/" in f"/{path}/":
        raise HTTPException(status_code=404, detail="not found")
    return FileResponse(STATIC_DIR / "index.html")
"}

